// Fuzz differential harness: the large pseudo-random ABI batch in
// `test/fixtures/abi/fuzz.json` (regenerated by `node scripts/gen-abi-fuzz.mjs`,
// gold bytes from an independent ethers v6 reference) checked against the
// runtime in `src/utils/abi`:
//   - encodeAbiParameters must reproduce the gold bytes exactly;
//   - decodeAbiParameters(gold) must round-trip back to the revived values;
//   - encodePacked must reproduce the gold packed bytes exactly.
import { readFileSync } from 'node:fs'
import { describe, expect, test } from 'vitest'

import {
  type FixtureParameter,
  type FixtureValue,
  reviveValue,
  reviveValues,
} from '../../fixtures/abi/loader.js'
import { decodeAbiParameters } from '../../../src/utils/abi/decodeAbiParameters.js'
import { encodeAbiParameters } from '../../../src/utils/abi/encodeAbiParameters.js'
import { encodePacked } from '../../../src/utils/abi/encodePacked.js'

type EncodeCase = {
  name: string
  params: FixtureParameter[]
  values: FixtureValue[]
  encoded: `0x${string}`
}

type PackedCase = {
  name: string
  types: string[]
  values: FixtureValue[]
  encoded: `0x${string}`
}

type FuzzFixture = { params: EncodeCase[]; packed: PackedCase[] }

const fuzz = JSON.parse(
  readFileSync(
    new URL('../../../test/fixtures/abi/fuzz.json', import.meta.url),
    'utf8',
  ),
) as FuzzFixture

describe('encodeAbiParameters (fuzz differential)', () => {
  test.each(
    fuzz.params.map((c) => [c.name, c] as const),
  )('%s encodes byte-exact', (_name, c) => {
    const values = reviveValues(c.params, c.values)
    expect(encodeAbiParameters(c.params, values as never)).toBe(c.encoded)
  })

  test.each(
    fuzz.params.map((c) => [c.name, c] as const),
  )('%s decodes round-trip', (_name, c) => {
    const expected = reviveValues(c.params, c.values)
    expect(decodeAbiParameters(c.params, c.encoded)).toEqual(expected)
  })

  test('covers >=250 encode cases', () => {
    expect(fuzz.params.length).toBeGreaterThanOrEqual(250)
  })
})

describe('encodePacked (fuzz differential)', () => {
  test.each(
    fuzz.packed.map((c) => [c.name, c] as const),
  )('%s packs byte-exact', (_name, c) => {
    const values = c.types.map((type, i) =>
      reviveValue({ type } as FixtureParameter, c.values[i] as FixtureValue),
    )
    expect(encodePacked(c.types, values as never)).toBe(c.encoded)
  })

  test('covers >=60 packed cases', () => {
    expect(fuzz.packed.length).toBeGreaterThanOrEqual(60)
  })
})
